package com.ruoyi.paicli.service;

import com.ruoyi.paicli.domain.*;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.stereotype.Service;
import java.nio.file.Files;
import java.util.*;

/** 枚举RPC复用现有业务服务；能力永远不能变成任意URL或跨会话代理。 */
@Service
@ConditionalOnProperty(prefix="paicli",name="enabled",havingValue="true")
public class PcTerminalClientGateway {
    private final PcTerminalService terminals;private final PcSessionService sessions;private final PcCommandService commands;private final PcArtifactService artifacts;private final PcStore store;private final PcAccess access;
    public PcTerminalClientGateway(PcTerminalService t,PcSessionService s,PcCommandService c,PcArtifactService ar,PcStore st,PcAccess ac){terminals=t;sessions=s;commands=c;artifacts=ar;store=st;access=ac;}
    @org.springframework.transaction.annotation.Transactional("paicliTransactionManager")
    public Object execute(PcTerminalService.CapabilityIdentity identity,String op,Map<String,Object> params){
        PcRecord bound=terminals.boundSession(identity);long session=bound.getId(),user=identity.user().getUserId();
        if(params.get("sessionId")!=null&&PcJson.number(params,"sessionId")!=session)throw PcException.deny("能力只能访问绑定会话");
        String key=Objects.toString(params.get("requestId"),UUID.randomUUID().toString());if(key.length()>128)throw PcException.invalid("请求标识过长");
        switch(op){
            case "open"->{permission(identity,"paicli:session:read");Map<String,Object> request=params.get("request") instanceof Map<?,?>?PcJson.object(params,"request"):params;for(String field:List.of("sessionId","directoryContextId","runnerId"))if(request.get(field)!=null&&!Objects.toString(request.get(field)).isBlank()){long expected=field.equals("sessionId")?session:field.equals("directoryContextId")?bound.getDirectoryContextId():bound.getRunnerId();if(Long.parseLong(String.valueOf(request.get(field)))!=expected)throw PcException.deny("CLI启动归属与终端绑定不一致");}Map<String,Object> detail=sessions.detail(session,user);String mode=PcJson.text(detail,"mode");if("REACT".equals(mode))mode=Objects.toString(detail.get("approvalMode"),"ASK");return Map.of("id",String.valueOf(session),"directoryContextId",String.valueOf(bound.getDirectoryContextId()),"runnerId",String.valueOf(bound.getRunnerId()),"mode",mode.toLowerCase(Locale.ROOT),"provider",Objects.toString(detail.get("provider"),""),"model",Objects.toString(detail.get("model"),""),"modelId",Objects.toString(detail.get("modelId"),""),"lastSequence",number(detail,"eventCursor",bound.getSequenceNumber()));}
            case "submit"->{
                permission(identity,"paicli:session:write");String mode=Objects.toString(params.get("mode"),"ask").toUpperCase(Locale.ROOT);if(!Set.of("AUTO","ASK","PLAN","TEAM").contains(mode))throw PcException.invalid("终端模式无效");String text=PcJson.text(params,"text");if(text.isBlank())throw PcException.invalid("消息不能为空");Map<String,Object> input=new LinkedHashMap<>();input.put("text",text);input.put("mode",mode.equals("TEAM")?"TEAM":mode.equals("PLAN")?"PLAN":"REACT");input.put("approvalMode",mode.equals("TEAM")?Objects.toString(store.data(bound).get("approvalMode"),"ASK"):mode);
                List<Long> ids=new ArrayList<>();Object raw=params.getOrDefault("attachments",List.of());if(!(raw instanceof List<?> images)||images.size()>10)throw PcException.invalid("每轮最多10张图片，沿用现有会话限制");
                for(Object value:images){if(!(value instanceof Map<?,?> untyped))throw PcException.invalid("附件结构非法");@SuppressWarnings("unchecked") Map<String,Object> image=(Map<String,Object>)untyped;String artifact=Objects.toString(image.get("artifactId"),"");if(!artifact.isBlank()){
                        long id=Long.parseLong(artifact);if(!terminals.attachmentAllowed(identity,id))throw PcException.deny("图片未经本终端当前输入请求批准");PcRecord row=access.resource(PcTable.ARTIFACT,id,user,true,false);if(!"TURN_IMAGE".equals(row.getKind())||!Objects.equals(row.getDirectoryContextId(),bound.getDirectoryContextId())||row.getSessionId()!=null&&!Objects.equals(row.getSessionId(),session))throw PcException.deny("附件归属不匹配");PcArtifactService.ArtifactContent content=artifacts.content(user,id);if(content.size()>PcArtifactService.MAX_API_IMAGE_BYTES||!content.sha256().equals(store.data(row).get("sha256")))throw PcException.deny("附件摘要或容量已改变");ids.add(id);
                    }else{String base64=PcJson.text(image,"base64Data");if(base64.length()>7*1024*1024)throw new PcException(413,"PC_IMAGE_SIZE","图片编码超限");byte[] bytes;try{bytes=Base64.getDecoder().decode(base64);}catch(IllegalArgumentException malformed){throw PcException.invalid("图片base64无效");}Map<String,Object> uploaded=artifacts.upload(user,key+":image:"+ids.size(),bound.getDirectoryContextId(),"TURN_IMAGE",PcJson.text(image,"name"),PcJson.text(image,"mimeType"),bytes);ids.add(PcJson.number(uploaded,"id"));}}
                input.put("attachments",ids);Map<String,Object> result=sessions.turn(session,user,key,bound.getVersion(),input);terminals.consumeAttachments(identity,ids);return Map.of("id",Objects.toString(result.get("taskId")),"status","ENQUEUED");
            }
            case "command"->{permission(identity,"paicli:session:write");String name=PcJson.text(params,"name"),arguments=PcJson.text(params,"arguments");if(name.equals("snapshot")&&arguments.strip().matches("clean\\s+all")){permission(identity,"paicli:snapshot:restore");return result("等待网页用户确认跨目录快照清理",terminals.authorizationRequest(identity));}Map<String,Object> taskBridge=taskBridge(identity,bound,user,name,arguments);if(taskBridge!=null)return taskBridge;commandScope(identity,bound,user,name,arguments);Map<String,Object> bridge=approvalBridge(identity,bound,name,arguments);if(bridge!=null)return bridge;if(createsAssociatedTask(name,arguments))terminals.ensureTaskCapacity(identity);Map<String,Object> result=commands.command(user,session,key,name,arguments);if(createsAssociatedTask(name,arguments))terminals.registerCommandTasks(identity,result);return result;}
            case "events"->{permission(identity,"paicli:session:read");Map<String,Object> result=sessions.events(session,user,number(params,"afterSequence",0),(int)number(params,"limit",200));return eventRecords(result);}
            case "taskEvents"->{permission(identity,"paicli:task:read");long task=PcJson.number(params,"taskId");task(identity,bound,user,task);return eventRecords(sessions.taskEvents(task,user,number(params,"afterSequence",0),null,(int)number(params,"limit",200)));}
            case "taskLog"->{permission(identity,"paicli:task:read");long id=PcJson.number(params,"taskId");task(identity,bound,user,id);long limit=number(params,"limit",200);if(limit<1||limit>200||!params.containsKey("endSequence"))throw PcException.invalid("任务日志须固定截止序号且limit为1–200");return result("任务日志分页已读取",sessions.taskEvents(id,user,number(params,"afterSequence",0),number(params,"endSequence",0),(int)limit));}
            case "readTaskArtifactText"->{permission(identity,"paicli:task:read");permission(identity,"paicli:session:read");long id=PcJson.number(params,"taskId");PcRecord task=task(identity,bound,user,id);long artifact=PcJson.number(params,"artifactId");PcRecord row=access.resource(PcTable.ARTIFACT,artifact,user,true,false);if(!Objects.equals(row.getParentId(),id)||!Objects.equals(row.getSessionId(),task.getSessionId())||!Objects.equals(row.getDirectoryContextId(),task.getDirectoryContextId()))throw PcException.deny("日志产物不属于指定关联任务");return result("任务完整产物分段已读取",artifacts.outputText(user,artifact,task.getSessionId(),number(params,"offset",0),(int)number(params,"limit",65536)));}
            case "cancel"->{permission(identity,"paicli:task:cancel");long id=PcJson.number(params,"turnId");PcRecord row=task(identity,bound,user,id);controlTask(identity,bound,row);sessions.cancel(id,user,row.getVersion(),key);return Map.of();}
            case "readLedger"->{permission(identity,"paicli:session:export");Map<String,Object> data=sessions.ledger(session,user,number(params,"afterSequence",0),number(params,"endSequence",bound.getSequenceNumber()),(int)number(params,"limit",200),raw(identity));return result("账本分页已读取",data);}
            case "readExportSection"->{permission(identity,"paicli:session:export");String section=PcJson.text(params,"section");if(!Set.of("events","plans","summaries","artifacts","toolCalls","approvals").contains(section))throw PcException.invalid("导出集合未登记");long limit=number(params,"limit",200);if(limit<1||limit>200||!params.containsKey("endId"))throw PcException.invalid("导出分页须固定endId且limit为1–200");return result("导出集合分页已读取",sessions.exportSection(session,user,section,number(params,"afterId",0),number(params,"endId",0),(int)limit,raw(identity)));}
            case "exportPublish"->{
                permission(identity,"paicli:session:export");Object source=params.get("files");if(!(source instanceof List<?> files)||files.isEmpty()||files.size()>2)throw PcException.invalid("每次只发布1–2份Markdown/JSON导出");List<Map<String,Object>> published=new ArrayList<>();Set<String> formats=new HashSet<>();long total=0;
                for(Object item:files){if(!(item instanceof Map<?,?> file))throw PcException.invalid("导出文件结构非法");String name=Objects.toString(file.get("name"),""),mime=Objects.toString(file.get("mimeType"),"");String format=name.endsWith(".json")?"json":name.endsWith(".md")?"md":"";if(format.isEmpty()||!formats.add(format))throw PcException.invalid("每批导出每种格式最多一份");String base64=Objects.toString(file.get("base64Data"),"");if(base64.length()>23*1024*1024)throw new PcException(413,"PC_EXPORT_SIZE","导出编码超限");byte[] bytes;try{bytes=Base64.getDecoder().decode(base64);}catch(IllegalArgumentException malformed){throw PcException.invalid("导出base64无效");}total+=bytes.length;if(total>24*1024*1024)throw new PcException(413,"PC_EXPORT_SIZE","终端导出每批限24MiB");Map<String,Object> artifact=artifacts.publishSessionExport(user,key+":"+format,session,name,mime,bytes);published.add(artifact);}
                terminals.exportReady(identity,published);return result("导出已保存到中心私有产物，可在网页下载",Map.of("artifacts",published,"sessionId",String.valueOf(session)));
            }
            case "readArtifactText"->{permission(identity,"paicli:session:read");long id=PcJson.number(params,"artifactId");PcRecord row=access.resource(PcTable.ARTIFACT,id,user,true,false);long scope=session;if(!Objects.equals(row.getSessionId(),session)){if(row.getParentId()==null||row.getSessionId()==null||!terminals.associatedTask(identity,row.getParentId()))throw PcException.deny("工具产物不属于当前会话或本终端创建的关联任务");scope=row.getSessionId();}return result("产物分段已读取",artifacts.outputText(user,id,scope,number(params,"offset",0),(int)number(params,"limit",65536)));}
            case "attachmentRequest"->{permission(identity,"paicli:session:write");return terminals.attachmentRequest(identity,params);}
            case "attachmentPoll"->{Map<String,Object> poll=terminals.attachmentPoll(identity,params);String state=PcJson.text(poll,"state");poll.put("status",state);if("READY".equals(state)&&poll.get("artifactIds") instanceof List<?> ids){List<Map<String,Object>> images=new ArrayList<>();for(Object id:ids){PcArtifactService.ArtifactContent content=artifacts.content(user,Long.parseLong(String.valueOf(id)));images.add(Map.of("artifactId",String.valueOf(id),"name",content.fileName(),"mimeType",content.mimeType(),"base64Data","","sha256",content.sha256(),"size",content.size()));}poll.put("attachments",images);}return poll;}
            case "attachmentCancel"->{return terminals.attachmentCancel(identity,params);}
            case "authorizationPoll"->{return terminals.authorizationPoll(identity,params,false);}
            case "authorizationCancel"->{return terminals.authorizationPoll(identity,params,true);}
            case "attachmentContent"->{long id=PcJson.number(params,"artifactId");if(!terminals.attachmentAllowed(identity,id))throw PcException.deny("图片未绑定本终端请求");PcArtifactService.ArtifactContent content=artifacts.content(user,id);if(content.size()>PcArtifactService.MAX_API_IMAGE_BYTES)throw new PcException(413,"PC_IMAGE_SIZE","图片容量超限");try{return Map.of("artifactId",String.valueOf(id),"name",content.fileName(),"mimeType",content.mimeType(),"base64Data",Base64.getEncoder().encodeToString(Files.readAllBytes(content.file())),"sha256",content.sha256(),"size",content.size());}catch(java.io.IOException failure){throw new PcException(503,"PC_IMAGE_STORAGE","图片读取失败，不能丢失图片继续提交");}}
            default->throw PcException.deny("未登记的终端Gateway操作");
        }
    }
    private void permission(PcTerminalService.CapabilityIdentity identity,String value){PcTerminalService.permission(identity.user(),value);}
    private boolean raw(PcTerminalService.CapabilityIdentity identity){return identity.user().getUser().isAdmin()||identity.user().getPermissions()!=null&&(identity.user().getPermissions().contains("*:*:*")||identity.user().getPermissions().contains("paicli:context:raw"));}
    private Map<String,Object> approvalBridge(PcTerminalService.CapabilityIdentity identity,PcRecord session,String name,String args){if(!Set.of("approval","approve","reject").contains(name))return null;String[] words=args.strip().split("\\s+");if(words.length<1||args.isBlank())return null;long id=Long.parseLong(name.equals("approval")&&words.length>1?words[1]:words[0]);PcRecord row=store.require(PcTable.APPROVAL,id,false);if(Objects.equals(row.getDirectoryContextId(),session.getDirectoryContextId()))return null;permission(identity,"paicli:approval:decide");if(row.getParentId()==null||!terminals.generatedTask(identity,row.getParentId()))throw PcException.deny("跨目录审批必须是本终端关联任务");if(name.equals("approval")&&"show".equals(words[0]))return result("关联任务审批的冻结参数",terminals.associatedApproval(identity,id));Map<String,Object> input=new LinkedHashMap<>();String decision;if(name.equals("approval")){if(words.length<3||!"decide".equals(words[0]))throw PcException.invalid("approval decide缺少决定");decision=words[2].toUpperCase(Locale.ROOT);if(words.length>3)input.putAll(store.json.read(args.substring(args.indexOf(words[3]))));}else{decision=name.equals("approve")?"APPROVE":"REJECT";input.put("feedback",words.length>1?args.substring(args.indexOf(words[1])):"");}return result("等待网页用户确认关联目录审批",terminals.approvalAuthorization(identity,id,decision,input));}
    private PcRecord task(PcTerminalService.CapabilityIdentity identity,PcRecord session,long user,long id){PcRecord row=access.resource(PcTable.TASK,id,user,true,false);if(!Objects.equals(row.getSessionId(),session.getId())&&!terminals.associatedTask(identity,id))throw PcException.deny("终端只能读取或取消绑定会话及本终端创建的关联任务");return row;}
    private boolean createsAssociatedTask(String name,String args){String[] words=args.strip().split("\\s+");String sub=words.length==0?"":words[0];if(name.equals("restore"))return true;if(name.equals("task"))return sub.equals("add");if(Set.of("mcp","browser","skill","wechat").contains(name)){if(name.equals("wechat")&&sub.equals("daemon")&&words.length>1)sub=words[1];return Set.of("on","enable","start","off","disable","stop","restart","pause","resume","reload","connect","setup","bind").contains(sub);}return false;}
    private void controlTask(PcTerminalService.CapabilityIdentity identity,PcRecord session,PcRecord task){if(!Objects.equals(task.getSessionId(),session.getId())&&!terminals.generatedTask(identity,task.getId()))throw PcException.deny("日志授权只允许读取；取消其他会话任务须通过/task cancel在网页单次确认");}
    private Map<String,Object> taskBridge(PcTerminalService.CapabilityIdentity identity,PcRecord session,long user,String name,String args){String[] words=args.strip().split("\\s+");if(!name.equals("task")||words.length!=2||!Set.of("log","cancel").contains(words[0]))return null;boolean cancel=words[0].equals("cancel");permission(identity,cancel?"paicli:task:cancel":"paicli:task:read");long id=Long.parseLong(words[1]);PcRecord task=access.resource(PcTable.TASK,id,user,true,false);if(Objects.equals(task.getSessionId(),session.getId())||(cancel?terminals.generatedTask(identity,id):terminals.associatedTask(identity,id)))return null;if(!Objects.equals(task.getDirectoryContextId(),session.getDirectoryContextId()))throw PcException.deny("不能授权当前目录以外的任意任务");return result("等待网页用户确认具体任务操作",terminals.taskAuthorization(identity,id,cancel));}
    private void commandScope(PcTerminalService.CapabilityIdentity identity,PcRecord session,long user,String name,String args){String[] words=args.strip().split("\\s+");if(name.equals("task")&&words.length>1&&Set.of("log","cancel").contains(words[0])){PcRecord target=task(identity,session,user,Long.parseLong(words[1]));if(words[0].equals("cancel"))controlTask(identity,session,target);}if(Set.of("approve","reject").contains(name)&&!args.isBlank()||name.equals("approval")&&words.length>1){long id=Long.parseLong(name.equals("approval")?words[1]:words[0]);PcRecord row=store.require(PcTable.APPROVAL,id,false);if(!Objects.equals(row.getSessionId(),session.getId())&&(row.getParentId()==null||!terminals.generatedTask(identity,row.getParentId())))throw PcException.deny("审批不属于绑定会话或本终端关联任务");}if(name.equals("plan")&&words.length>1&&Set.of("execute","revise","cancel").contains(words[0])){PcRecord row=store.require(PcTable.PLAN,Long.parseLong(words[1]),false);if(!Objects.equals(row.getSessionId(),session.getId())&&(row.getParentId()==null||!terminals.generatedTask(identity,row.getParentId())))throw PcException.deny("计划不属于绑定会话或本终端关联任务");}}
    @SuppressWarnings("unchecked") private List<Map<String,Object>> eventRecords(Map<String,Object> value){List<Map<String,Object>> events=new ArrayList<>();if(value.get("events") instanceof List<?> list)for(Object item:list){Map<String,Object> record=(Map<String,Object>)item;Map<String,Object> payload=new LinkedHashMap<>((Map<String,Object>)record.getOrDefault("payload",Map.of()));if(record.get("taskId")!=null)payload.put("taskId",String.valueOf(record.get("taskId")));String type=Objects.toString(record.get("type"),"");events.add(Map.of("sequence",number(record,"sequence",0),"type",type,"payload",payload,"terminal",Boolean.TRUE.equals(record.get("terminal"))||type.matches("TASK_(COMPLETED|FAILED|CANCELLED)")));}return events;}
    private static Map<String,Object> result(String message,Map<String,Object> data){return Map.of("successful",true,"message",message,"data",data);}
    private static long number(Map<String,Object> input,String field,long fallback){Object value=input.get(field);if(value==null)return fallback;try{return Long.parseLong(String.valueOf(value));}catch(Exception invalid){throw PcException.invalid(field+"须为整数");}}
}
